-- ACMP I-V бөлімдеріндегі жаңа дәрістерге орысша слайд нұсқаларын қосу.
-- Қайта орындауға болады: тек осы 15 дәрістің ru өрістері жаңартылады.

do $acmp_foundations_ru$
declare
  v_owner uuid;
  v_spec record;
  v_slides jsonb;
  v_lesson_id uuid;
begin
  select owner_id into v_owner
  from public.cf_curr_courses
  where id = 'dbe60970-1fa6-4a8a-a65e-051d20cfd278'
    and title = 'ACMP: Язык программирования C++';

  if v_owner is null then
    raise exception 'ACMP курсы табылмады';
  end if;

  for v_spec in
    select * from jsonb_to_recordset($spec$
    [
      {"title":"Арифметика","title_ru":"Арифметика","summary_ru":"Первые задачи на C++: ввод, вывод и арифметические операции.","theory_ru":["Переменная хранит данные: int — целое число, double — вещественное число.","Основные операции: + сложение, - вычитание, * умножение, / деление, % остаток.","При делении целых чисел результат тоже целый: 7 / 2 = 3.","Скобки помогают явно задать порядок вычислений."],"algorithm_ru":["Прочитайте входные данные.","Выполните операции формулы в правильном порядке.","Выведите результат в требуемом формате."],"tasks_ru":["A. A+B","B. Глухонемой телефон","C. Бусинки","D. Эния","E. Следующее и предыдущее","F. Два бандита"],"statement_ru":"Даны два целых числа A и B. Найдите их сумму.\n\nВходные данные: в одной строке файла INPUT.TXT записаны два целых числа A и B.\n\nВыходные данные: выведите значение A+B в файл OUTPUT.TXT.\n\nПример: вход: 2 3. Выход: 5.","explanation_ru":"Дополнительные циклы и условия не нужны. Достаточно прочитать два числа и выполнить одну арифметическую операцию.","data_ru":"int: a, b, answer.","pseudo_ru":"прочитать a, b\nanswer ← a + b\nвывести answer"},
      {"title":"Қарапайым есептер","title_ru":"Простые задачи","summary_ru":"Чтение нескольких входных значений и выполнение простого преобразования по условию.","theory_ru":["Разделите условие на три части: что дано, что нужно найти и какие есть ограничения.","Если входные значения разделены пробелами или переводами строк, cin читает их одинаково.","Выводите только требуемое значение: лишний текст может привести к ошибке проверки ACMP.","При переводе единиц сначала запишите формулу на бумаге."],"algorithm_ru":["Выберите переменные по условию задачи.","Прочитайте все значения один раз.","Вычислите ответ по формуле.","Выведите ответ в одной строке."],"tasks_ru":["A. Hello world!","B. Дурак","C. Игра","D. Сокращение перерывов","E. A+B+C","F. Короли могут всё","G. Том и Джерри","H. Строки в книге"],"statement_ru":"Даны три целых числа A, B и C. Вычислите их сумму.\n\nВходные данные: в одной строке записаны три целых числа, разделённые пробелами.\n\nВыходные данные: выведите сумму трёх чисел.\n\nПример: вход: 1 2 3. Выход: 6.","explanation_ru":"Хотя вход состоит из нескольких чисел, cin последовательно читает их в отдельные переменные. Ответ — сумма трёх значений.","data_ru":"int: a, b, c, sum.","pseudo_ru":"прочитать a, b, c\nsum ← a + b + c\nвывести sum"},
      {"title":"Бүтін сандар","title_ru":"Целые числа","summary_ru":"Работа с цифрами целого числа, делением, остатком и свойствами числа.","theory_ru":["Операция / даёт целую часть частного, а % — остаток от деления.","Последняя цифра находится как n % 10, удаление последней цифры — как n / 10.","Чётное число удовлетворяет условию n % 2 == 0.","Цифры числа можно обрабатывать циклом while, пока число не станет нулём."],"algorithm_ru":["Учтите ограничения и знак числа.","Получите нужную цифру с помощью %.","Для перехода к следующей цифре используйте / 10.","Отдельно обработайте особый случай, например n=0."],"tasks_ru":["A. Пять пять — двадцать пять!","B. Последняя цифра","C. Количество десятков","D. Сумма цифр числа","E. Галстук","F. Проверьте делимость","G. Деление яблок","H. МКАД","I. Остаток от деления"],"statement_ru":"Дано трёхзначное целое число. Определите его последнюю цифру.\n\nВходные данные: в INPUT.TXT записано трёхзначное число.\n\nВыходные данные: выведите цифру единиц числа.\n\nПример: вход: 203. Выход: 3.","explanation_ru":"В десятичной системе последняя цифра равна остатку от деления числа на 10. Поэтому главная формула задачи — n % 10.","data_ru":"int: n, digit.","pseudo_ru":"прочитать n\ndigit ← n mod 10\nвывести digit"},
      {"title":"Формулаларды шығару","title_ru":"Вывод формул","summary_ru":"Перевод математических формул в выражения C++ и вывод вещественного результата с нужной точностью.","theory_ru":["Функции sqrt(x), abs(x), pow(x,y), sin(x), cos(x) доступны при подключении bits/stdc++.h.","Если ожидается вещественный результат, хотя бы один операнд должен иметь тип double.","fixed << setprecision(k) выводит ровно k цифр после десятичной точки.","Дроби и скобки из формулы нужно точно перенести в синтаксис C++."],"algorithm_ru":["Разбейте математическую формулу на части.","Переведите каждую часть в выражение C++.","Выберите тип double.","Выведите результат с требуемой точностью."],"tasks_ru":["A. Магазин канцтоваров","B. Гулливер","C. Журавлики","D. Разность времён","E. Окончание уроков","F. Улитка"],"statement_ru":"Даны катеты a и b прямоугольного треугольника. Найдите длину гипотенузы, площадь и периметр.\n\nВходные данные: a и b — положительные вещественные числа.\n\nВыходные данные: выведите гипотенузу, площадь и периметр с точностью 6 цифр после точки.\n\nПример: вход: 3 4. Выход: 5.000000 6.000000 12.000000.","explanation_ru":"По теореме Пифагора c = sqrt(a²+b²). Площадь равна S=ab/2, периметр P=a+b+c. Используем вещественный тип и setprecision.","data_ru":"double: a, b, c, area, perimeter.","pseudo_ru":"прочитать a, b\nc ← sqrt(a·a + b·b)\narea ← a·b / 2\nperimeter ← a + b + c\nвывести c, area, perimeter"},
      {"title":"Қарапайым салыстырулар","title_ru":"Простые сравнения","summary_ru":"Выбор одного из вариантов с помощью if, else и операторов сравнения.","theory_ru":["Операторы сравнения: <, >, <=, >=, ==, !=.","Если условие if истинно, выполняется его блок, иначе — блок else.","Несколько условий объединяются логическими операторами && и ||.","Для проверки равенства используется ==, а не =."],"algorithm_ru":["Перечислите все случаи из условия.","Определите, где нужна граница с равенством.","Дайте результат каждому случаю через if/else.","Проверьте меньшие, равные и большие значения."],"tasks_ru":["A. Больше-меньше","B. Арифметика","C. Счастливый билет","D. Зарплата","E. Баскетбол","F. Четырёхзначный палиндром","G. Торт","H. Три толстяка","I. Золотой песок","J. Светофор"],"statement_ru":"Даны два целых числа. Выведите большее из них. Если числа равны, выведите это же значение.\n\nВходные данные: в одной строке записаны целые числа a и b.\n\nВыходные данные: выведите max(a,b).\n\nПример: вход: 7 4. Выход: 7.","explanation_ru":"Для сравнения двух чисел достаточно одного if. Если a>b, выводим a, во всех остальных случаях — b; при равенстве значения одинаковы.","data_ru":"int: a, b.","pseudo_ru":"прочитать a, b\nесли a > b, вывести a\nиначе вывести b"},
      {"title":"Шахмат","title_ru":"Шахматы","summary_ru":"Проверка ходов шахматных фигур по координатам клеток доски.","theory_ru":["Клетки шахматной доски задаются координатами строки и столбца от 1 до 8.","Ладья ходит по одной строке или одному столбцу: x1==x2 или y1==y2.","Слон ходит по диагонали: |x1-x2| == |y1-y2|.","Для коня разности координат равны 1 и 2 в любом порядке."],"algorithm_ru":["Прочитайте начальные и конечные координаты.","Вычислите разности по x и y.","Сравните их с условием хода фигуры.","Выведите YES или NO."],"tasks_ru":["A. Ладья","B. Слон","C. Ферзь","D. Король","E. Конь","F. Пешка","G. Клетки","H. Шахматная доска","I. Игра с ладьёй","J. Шахматные фигуры"],"statement_ru":"На шахматной доске заданы начальная и конечная клетки ладьи. Может ли ладья сделать этот ход за один ход?\n\nВходные данные: x1, y1, x2, y2 — координаты от 1 до 8.\n\nВыходные данные: выведите YES, если ход возможен, и NO иначе.\n\nПример: вход: 1 2 1 8. Выход: YES.","explanation_ru":"Ладья ходит горизонтально или вертикально. Поэтому ход возможен, если строки совпадают или совпадают столбцы.","data_ru":"int: x1, y1, x2, y2, dx, dy.","pseudo_ru":"прочитать x1, y1, x2, y2\nесли x1=x2 или y1=y2, вывести YES\nиначе вывести NO"},
      {"title":"Күрделі есептер","title_ru":"Сложные задачи","summary_ru":"Полный разбор нескольких взаимосвязанных условий и проверка всех возможных случаев.","theory_ru":["Для сложной условной задачи полезно сначала выписать случаи в таблицу.","Ранний выход и отдельные if-блоки делают код понятнее.","Условия не должны пересекаться и пропускать возможные входные данные.","Ограничения задачи нужно учитывать прямо в условиях."],"algorithm_ru":["Разделите задачу на случаи.","Запишите необходимое условие для каждого случая.","Проверяйте условия от простого к сложному.","Протестируйте граничные значения."],"tasks_ru":["A. Алиса, лиса и кот Базилио","B. Турист","C. Котлеты","D. Манхэттенский полицейский"],"statement_ru":"По трём сторонам a, b и c определите вид треугольника. Если треугольник не существует, выведите 0; если он равносторонний — 3; равнобедренный — 2; иначе — 1.\n\nВходные данные: положительные целые числа a, b и c.\n\nВыходные данные: выведите соответствующий код.\n\nПример: вход: 3 3 4. Выход: 2.","explanation_ru":"Сначала проверяем существование треугольника. Только после этого анализируем равенство сторон, иначе неправильный треугольник может получить неверный тип.","data_ru":"int: a, b, c.","pseudo_ru":"прочитать a, b, c\nесли треугольник не существует, вывести 0\nиначе если все стороны равны, вывести 3\nиначе если две стороны равны, вывести 2\nиначе вывести 1"},
      {"title":"Параметрлі цикл (for)","title_ru":"Цикл с параметром (for)","summary_ru":"Цикл for для случаев, когда количество повторений известно заранее.","theory_ru":["У цикла for есть начальное значение, условие продолжения и шаг изменения.","for (int i=1; i<=n; ++i) — классический цикл от 1 до n.","Внутри цикла можно считать сумму, произведение, количество и строить таблицы.","При выборе i<n или i<=n учитывайте нумерацию в условии."],"algorithm_ru":["Определите число итераций.","Запишите начальное и конечное значение счётчика.","Укажите действие на каждой итерации.","Проверьте случаи n=0 и n=1."],"tasks_ru":["A. Монеты","B. Арбузы","C. Конечные автоматы","D. Автобусная экскурсия","E. Перепись населения","F. Загадка","G. Дороги","H. Сумма","I. Уравнение","J. Оттепель"],"statement_ru":"Дано натуральное число N. Найдите сумму всех чисел от 1 до N.\n\nВходные данные: число N.\n\nВыходные данные: выведите сумму 1+2+...+N.\n\nПример: вход: 5. Выход: 15.","explanation_ru":"Начинаем сумму с нуля и на каждом шаге цикла добавляем i. Цикл for подходит, потому что число повторений заранее известно.","data_ru":"int: n, i; long long: sum.","pseudo_ru":"прочитать n\nsum ← 0\nдля i=1..n: sum ← sum+i\nвывести sum"},
      {"title":"Алдын ала шарты тексерілетін цикл (while)","title_ru":"Цикл с предусловием (while)","summary_ru":"Цикл while и условие остановки, когда количество повторений заранее неизвестно.","theory_ru":["while сначала проверяет условие, поэтому тело может не выполниться ни разу.","Внутри цикла обязательно должна изменяться переменная, влияющая на условие.","Цикл удобен для обработки цифр, поиска делителей и ввода неизвестной длины.","Заранее найдите ситуацию, в которой условие станет ложным."],"algorithm_ru":["Определите, что сохраняется на каждой итерации.","Запишите условие while.","Изменяйте переменную внутри тела цикла.","После завершения выведите результат."],"tasks_ru":["A. Список квадратов","B. Наименьший делитель","C. Список степеней двойки","D. Двоичные числа","E. Числа Фибоначчи","F. Числа Фибоначчи — 2","G. Банковские проценты","H. Утренний бег","I. Сумма максимума и минимума"],"statement_ru":"Дано число N (N>1). Найдите его наименьший делитель, больший единицы.\n\nВходные данные: целое число N.\n\nВыходные данные: выведите наименьший делитель N, больший 1.\n\nПример: вход: 15. Выход: 3.","explanation_ru":"Начинаем проверку делителей с d=2. Первое d, для которого N%d==0, является наименьшим делителем, поэтому цикл можно остановить.","data_ru":"int: n, d.","pseudo_ru":"прочитать n\nd ← 2\nпока n mod d ≠ 0: d ← d+1\nвывести d"},
      {"title":"ЕҮОБ және ЕКОЕ","title_ru":"НОД и НОК","summary_ru":"Алгоритм Евклида для нахождения наибольшего общего делителя и наименьшего общего кратного.","theory_ru":["НОД(a,b) — самый большой общий делитель двух чисел.","Алгоритм Евклида: gcd(a,b)=gcd(b,a%b); при b=0 ответ равен a.","НОК(a,b)=a/gcd(a,b)*b.","Сначала делите, потом умножайте — так меньше риск переполнения."],"algorithm_ru":["Прочитайте a и b.","Повторяйте шаг Евклида, пока остаток не станет нулём.","Используйте найденный НОД для вычисления НОК.","Для больших чисел выберите long long."],"tasks_ru":["A. НОД","B. НОК","C. Апельсины","D. Числа Фибоначчи — 3"],"statement_ru":"Даны два натуральных числа a и b. Найдите их наибольший общий делитель.\n\nВходные данные: натуральные числа a и b.\n\nВыходные данные: выведите НОД(a,b).\n\nПример: вход: 18 24. Выход: 6.","explanation_ru":"Вместо проверки всех делителей используем последовательность остатков. Алгоритм работает быстро — за O(log(min(a,b))).","data_ru":"long long: a, b, r, g.","pseudo_ru":"прочитать a, b\nпока b ≠ 0: r ← a mod b; a ← b; b ← r\nвывести a"},
      {"title":"Жол түрі (string)","title_ru":"Строковый тип (string)","summary_ru":"Чтение строки, обращение к символам, поиск и преобразование текста средствами C++.","theory_ru":["string — последовательность символов; индекс первого символа равен 0.","s.size() и s.length() возвращают длину строки.","s[i] обращается к i-му символу, а s.substr(k,n) выделяет подстроку.","getline(cin,s) читает строку вместе с пробелами; это отличается от cin >> s."],"algorithm_ru":["Прочитайте строку подходящим способом.","Помните, что индексы находятся в диапазоне 0..size()-1.","Просмотрите символы циклом и посчитайте или измените нужные.","Выведите результат или изменённую строку."],"tasks_ru":["A. Клавиатура","B. Цветы","C. Число E","D. Шахматы","E. Стрелки","F. Измени порядок","G. Рунные слова","H. Шифрование","I. Золото племени АББА"],"statement_ru":"Дано слово из строчных латинских букв. Определите количество гласных букв. Гласные: a, e, i, o, u, y.\n\nВходные данные: одно слово длиной не более 100 символов.\n\nВыходные данные: выведите количество гласных.\n\nПример: вход: program. Выход: 2.","explanation_ru":"Просматриваем все символы слова один раз. Если символ входит в множество гласных, увеличиваем счётчик.","data_ru":"string: s; int: vowels; char: c.","pseudo_ru":"прочитать s\nvowels ← 0\nдля каждого символа c: если c гласный, vowels++\nвывести vowels"},
      {"title":"Санау жүйелері","title_ru":"Системы счисления","summary_ru":"Двоичная, восьмеричная, десятичная и шестнадцатеричная системы счисления и перевод чисел.","theory_ru":["В системе с основанием b используются цифры от 0 до b-1.","Перевод из десятичной системы: делите число на b и записывайте остатки в обратном порядке.","Перевод в десятичную: слева направо применяйте формулу ans=ans*b+digit.","В шестнадцатеричной системе после 9 используются A..F."],"algorithm_ru":["Определите основание и число.","Преобразуйте каждый символ в числовое значение.","Обновляйте значение с учётом основания.","Соберите результат в нужной системе счисления."],"tasks_ru":["A. Единицы","B. Несложное вычисление","C. Unix","D. Битовый реверс","E. Минимальная система счисления","F. Число — палиндром","G. Интересная игра","H. Делимость на 7","I. Система счисления","J. ЕГЭ","K. Взвешивание","L. Система счисления Фибоначчи"],"statement_ru":"Переведите целое неотрицательное число N в систему счисления с основанием B.\n\nВходные данные: N — неотрицательное целое число, 2≤B≤16.\n\nВыходные данные: выведите запись N в системе с основанием B; цифры больше 9 обозначайте заглавными буквами A-F.\n\nПример: вход: 26 16. Выход: 1A.","explanation_ru":"Остатки при последовательном делении N на основание начинаются с младшего разряда. Поэтому сначала собираем их, а затем выводим в обратном порядке.","data_ru":"long long: n; int: base, digit; string: answer.","pseudo_ru":"прочитать n, base\nесли n=0, вывести 0\nпока n>0: добавить digit=n mod base; n←n/base\nвывести answer в обратном порядке"},
      {"title":"Сызықтық іздеу","title_ru":"Линейный поиск","summary_ru":"Последовательный просмотр массива для поиска значения, минимума, максимума или количества совпадений.","theory_ru":["Линейный поиск проверяет элементы по порядку и не требует сортировки массива.","Чтобы посчитать все совпадения, увеличивайте счётчик.","При поиске первого совпадения можно использовать break.","Для минимума и максимума безопасно начать с первого элемента массива."],"algorithm_ru":["Прочитайте N и элементы массива.","Сравните каждый элемент с искомым значением.","При совпадении обновите счётчик или ответ.","Выведите итоговый результат."],"tasks_ru":["A. Линейный поиск","B. Максимальный элемент","C. Обратная операция","D. Сбор черники","E. Ближайшее число","F. Налоги"],"statement_ru":"Дан массив из N целых чисел и число X. Определите, сколько раз X встречается в массиве.\n\nВходные данные: N, X и N элементов массива.\n\nВыходные данные: выведите количество вхождений X.\n\nПример: вход: 5 3 и массив 1 3 3 2 4. Выход: 2.","explanation_ru":"Каждый элемент сравнивается с X ровно один раз. При равенстве увеличиваем счётчик. Сложность алгоритма O(N).","data_ru":"int: n, x, a, count.","pseudo_ru":"прочитать n, x\ncount ← 0\nN раз: прочитать a; если a=x, count++\nвывести count"},
      {"title":"Деректерді түрлендіру және талдау","title_ru":"Преобразование и анализ данных","summary_ru":"Поэлементная обработка массива: суммы, статистика, преобразования и анализ соседних значений.","theory_ru":["Массив хранит элементы одного типа и позволяет обращаться к ним по индексу.","Сумму, количество и среднее удобно вычислять одним проходом.","При изменении массива отличайте исходное значение от уже изменённого.","Для статистики заранее определите, какие значения нужно хранить: сумму, минимум, максимум или счётчик."],"algorithm_ru":["Прочитайте размер и массив.","Инициализируйте переменные анализа.","Просмотрите элементы и обновляйте нужные показатели.","Выведите вычисленные характеристики."],"tasks_ru":["A. Обратная запись","B. Подмассив массива","C. Очередь","D. Двойная обратная запись","E. Сдвиг перестановки","F. Статистика","G. Домашнее задание","H. Суперсдвиг","I. Волосатый бизнес","J. Пересечение множеств"],"statement_ru":"Дана последовательность целых чисел. Найдите сумму всех элементов до первого нуля; сам ноль в последовательность не входит.\n\nВходные данные: неотрицательные целые числа, среди которых гарантированно есть ноль.\n\nВыходные данные: выведите сумму элементов до первого нуля.\n\nПример: вход: 1 7 9 0 5. Выход: 17.","explanation_ru":"Читаем элементы по очереди. Ноль является признаком окончания: его не добавляем и сразу завершаем обработку.","data_ru":"long long: x, sum.","pseudo_ru":"sum ← 0\nпока читать x и x≠0: sum ← sum+x\nвывести sum"},
      {"title":"Құрылымдар массиві","title_ru":"Массивы структур","summary_ru":"Объединение связанных свойств объекта в struct и обработка массива таких объектов.","theory_ru":["struct создаёт новый тип данных: несколько полей хранятся в одной записи.","К полю обращаются через точку: student.name, student.score.","Массив структур можно читать, фильтровать и сортировать циклом.","Тип каждого поля выбирайте по условию: string, int или double."],"algorithm_ru":["Определите поля одной записи.","Опишите структуру struct.","Прочитайте N объектов.","Найдите, посчитайте или отсортируйте нужные объекты."],"tasks_ru":["A. Точки на плоскости","B. Телефонный справочник","C. Лучшие из лучших"],"statement_ru":"Даны имена и баллы N учеников. Выведите имена учеников, набравших не менее 90 баллов.\n\nВходные данные: N, затем N строк с именем и целым баллом.\n\nВыходные данные: выведите имена подходящих учеников в исходном порядке.\n\nПример: вход: 3; Ayan 95; Dana 84; Miras 90. Выход: Ayan Miras.","explanation_ru":"Имя и балл принадлежат одному объекту, поэтому храним их в структуре Student. Для каждой записи проверяем поле score.","data_ru":"struct Student { string name; int score; }; Student a[100].","pseudo_ru":"прочитать n\nN раз: прочитать a[i].name, a[i].score\nесли a[i].score≥90, вывести имя"}
    ]
    $spec$::jsonb) as x(
      title text, title_ru text, summary_ru text, theory_ru jsonb,
      algorithm_ru jsonb, tasks_ru jsonb, statement_ru text,
      explanation_ru text, data_ru text, pseudo_ru text
    )
  loop
    select l.id, l.slides into v_lesson_id, v_slides
    from public.cf_lessons l
    where l.owner_id = v_owner and l.title = v_spec.title
    limit 1;

    if v_lesson_id is null or jsonb_array_length(v_slides) < 6 then
      continue;
    end if;

    v_slides := jsonb_set(v_slides, '{0,ru}', jsonb_build_object(
      'title',v_spec.title_ru,
      'subtitle','ACMP: Язык программирования C++ · теория и задачи'
    ), true);
    v_slides := jsonb_set(v_slides, '{1,ru}', jsonb_build_object(
      'title','Основные понятия','bullets',v_spec.theory_ru
    ), true);
    v_slides := jsonb_set(v_slides, '{2,ru}', jsonb_build_object(
      'title','Пример на C++','prompt','Прочитайте код по шагам: ввод → основное действие → вывод.',
      'notes','Проверьте код на собственном тесте и объясните тип каждой переменной.'
    ), true);
    v_slides := jsonb_set(v_slides, '{3,ru}', jsonb_build_object(
      'title','Алгоритм задачи','bullets',v_spec.algorithm_ru
    ), true);
    v_slides := jsonb_set(v_slides, '{4,ru}', jsonb_build_object(
      'title','Задачи ACMP из PDF','bullets',v_spec.tasks_ru,
      'prompt','Все названия взяты из указателя задач PDF. Сначала попробуйте решить каждую задачу самостоятельно.'
    ), true);
    v_slides := jsonb_set(v_slides, '{5,ru}', jsonb_build_object(
      'title',v_spec.title_ru || ' · пример задачи', 'problemPage',true,
      'answerHidden',true,
      'sections',jsonb_build_array(
        jsonb_build_object('h','Условие задачи','text',v_spec.statement_ru),
        jsonb_build_object('h','Объяснение задачи','text',v_spec.explanation_ru),
        jsonb_build_object('h','Алгоритм задачи','text',(select string_agg(value, E'\n' order by ord) from jsonb_array_elements_text(v_spec.algorithm_ru) with ordinality as t(value,ord))),
        jsonb_build_object('h','Структура данных','text',v_spec.data_ru),
        jsonb_build_object('h','Псевдокод','text',v_spec.pseudo_ru),
        jsonb_build_object('h','Решение задачи (скрыто)','hide',true,'code',v_slides->5->'sections'->5->>'code','lang','C++')
      )
    ), true);

    update public.cf_lessons
    set slides = v_slides, updated_at = now()
    where id = v_lesson_id;
  end loop;
end;
$acmp_foundations_ru$;
